public class PortfolioOptimizerService : IPortfolioOptimizer
{
    public async Task<Portfolio> OptimizeAllocation(
        Portfolio currentPortfolio,
        RiskParameters riskParams,
        Dictionary<string, decimal> currentPrices,
        CancellationToken ct)
    {
        // 1. Calculate current portfolio metrics
        var currentMetrics = CalculatePortfolioMetrics(currentPortfolio, currentPrices);

        // 2. Determine target weights based on risk parameters
        var targetWeights = CalculateTargetWeights(currentMetrics, riskParams);

        // 3. Calculate target quantities for each asset
        var targetPortfolio = CalculateTargetQuantities(currentPortfolio, targetWeights, currentPrices);

        return targetPortfolio;
    }

