        return new Dictionary<string, decimal>();
    }

    private Portfolio CalculateTargetQuantities(Portfolio portfolio, Dictionary<string, decimal> targetWeights, Dictionary<string, decimal> prices)
    {
        var targetPortfolio = new Portfolio
        {
            Id = portfolio.Id,
            Name = portfolio.Name,
            LastRebalanceDate = DateTime.UtcNow,
            TargetWeights = targetWeights
        };

        // Calculate target quantities for each asset
        foreach (var asset in portfolio.Assets)
        {
            if (targetWeights.TryGetValue(asset.Symbol, out var targetWeight))
            {
                var targetValue = targetWeight * portfolio.TotalValue;
                var targetQuantity = targetValue / prices[asset.Symbol];
                asset.TargetQuantity = targetQuantity;
            }
        }

        targetPortfolio.Assets = portfolio.Assets;
        return targetPortfolio;
    }
}

// TradeExecutorService.cs
public class TradeExecutorService : ITradeExecutor
{
    private readonly ITradeRepository _tradeRepository;
    private readonly IMarketDataFeed _marketDataFeed;

    public TradeExecutorService(
        ITradeRepository tradeRepository,
        IMarketDataFeed marketDataFeed)
    {
        _tradeRepository = tradeRepository;
        _marketDataFeed = marketDataFeed;
    }

    public async Task ExecuteTradesAsync(
        Portfolio currentPortfolio,
        Portfolio targetPortfolio,
        Dictionary<string, decimal> currentPrices,
        CancellationToken ct)
    {
        var trades = new List<Trade>();

        foreach (var asset in currentPortfolio.Assets)
        {
            if (targetPortfolio.TargetWeights.TryGetValue(asset.Symbol, out var targetWeight))
            {
                var targetValue = targetWeight * currentPortfolio.TotalValue;
                var targetQuantity = targetValue / currentPrices[asset.Symbol];

                var quantityDifference = targetQuantity - asset.Quantity;

                if (quantityDifference > 0)
                {
                    trades.Add(new Trade
                    {
                        Symbol = asset.Symbol,
                        Quantity = quantityDifference,
                        Price = currentPrices[asset.Symbol],
                        Type = TradeType.Buy,
                        ExecutionTime = DateTime.UtcNow
                    });
                }
                else if (quantityDifference < 0)
                {
                    trades.Add(new Trade
                    {
                        Symbol = asset.Symbol,
                        Quantity = -quantityDifference,
                        Price = currentPrices[asset.Symbol],
                        Type = TradeType.Sell,
                        ExecutionTime = DateTime.UtcNow
                    });
                }
            }
        }

        // Execute trades (in a real implementation, this would connect to a broker)
        await _tradeRepository.ExecuteTradesAsync(trades, ct);

        // Update portfolio with new quantities
        await UpdatePortfolioWithTradesAsync(currentPortfolio, trades, ct);
    }

    private async Task UpdatePortfolioWithTradesAsync(
        Portfolio portfolio,
        List<Trade> trades,
        CancellationToken ct)
    {
        foreach (var trade in trades)
        {
            var asset = portfolio.Assets.FirstOrDefault(a => a.Symbol == trade.Symbol);
            if (asset != null)
            {
                if (trade.Type == TradeType.Buy)
                {
                    asset.Quantity += trade.Quantity;
                }
                else
                {
                    asset.Quantity -= trade.Quantity;
                }
            }
        }

        // Update portfolio value
        portfolio.TotalValue = portfolio.Assets.Sum(a => a.Quantity * currentPrices[a.Symbol]) +
                              portfolio.CashBalance;
    }
}
