## 3. Rebalancing Engine (Rebalancer/)

```csharp
// PortfolioRebalancer.cs
public class PortfolioRebalancer
{
    private readonly IMarketDataFeed _marketDataFeed;
    private readonly IPortfolioOptimizer _portfolioOptimizer;
    private readonly ITradeExecutor _tradeExecutor;
    private readonly IPortfolioRepository _portfolioRepository;
    private readonly TimeSpan _rebalanceInterval;

    public PortfolioRebalancer(
        IMarketDataFeed marketDataFeed,
        IPortfolioOptimizer portfolioOptimizer,
        ITradeExecutor tradeExecutor,
        IPortfolioRepository portfolioRepository,
        TimeSpan rebalanceInterval)
    {
        _marketDataFeed = marketDataFeed;
        _portfolioOptimizer = portfolioOptimizer;
        _tradeExecutor = tradeExecutor;
        _portfolioRepository = portfolioRepository;
        _rebalanceInterval = rebalanceInterval;
    }

    public async Task RebalancePortfolioAsync(string portfolioId, RiskParameters riskParams, CancellationToken ct)
    {
        // 1. Get current portfolio
        var currentPortfolio = await _portfolioRepository.GetPortfolioAsync(portfolioId, ct);

        // 2. Get current market data
        var currentPrices = await _marketDataFeed.GetCurrentPricesAsync(ct);

        // 3. Optimize portfolio allocation
        var targetPortfolio = await _portfolioOptimizer.OptimizeAllocation(
            currentPortfolio, riskParams, currentPrices, ct);

        // 4. Execute trades to reach target allocation
        await _tradeExecutor.ExecuteTradesAsync(
            currentPortfolio, targetPortfolio, currentPrices, ct);

        // 5. Update portfolio with new target weights
        targetPortfolio.LastRebalanceDate = DateTime.UtcNow;
        await _portfolioRepository.UpdatePortfolioAsync(targetPortfolio, ct);
    }
}

