var builder = WebApplication.CreateBuilder(args);

// Register services
builder.Services.AddSingleton<IMarketDataFeed, MarketDataFeedService>();
builder.Services.AddSingleton<IMarketDataRepository, MarketDataRepository>();
builder.Services.AddSingleton<IPortfolioRepository, PortfolioRepository>();
builder.Services.AddSingleton<IPortfolioOptimizer, PortfolioOptimizerService>();
builder.Services.AddSingleton<ITradeExecutor, TradeExecutorService>();
builder.Services.AddSingleton<ITradeRepository, TradeRepository>();

// Configure rebalancing engine
builder.Services.AddSingleton<PortfolioRebalancer>(sp =>
    new PortfolioRebalancer(
        sp.GetRequiredService<IMarketDataFeed>(),
        sp.GetRequiredService<IPortfolioOptimizer>(),
        sp.GetRequiredService<ITradeExecutor>(),
        sp.GetRequiredService<IPortfolioRepository>(),
        TimeSpan.FromHours(1)));

builder.Services.AddSingleton<RebalancingEngine>(sp =>
    new RebalancingEngine(
        sp.GetRequiredService<PortfolioRebalancer>(),
        TimeSpan.FromHours(1)));

// Start rebalancing engine
var app = builder.Build();
var rebalancingEngine = app.Services.GetRequiredService<RebalancingEngine>();

// Start rebalancing in background
Task.Run(async () => await rebalancingEngine.RebalanceAllPortfoliosAsync(default), default);

// Keep application running
